import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, PointLight } = ctx.THREE;

  const container = new Group();

  // Color Palette
  const palette = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // 1. Stage Backdrop local fill (to prevent FLAT_VOID)
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    color: palette.ink,
    roughness: 0.9,
    metalness: 0.1
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.5;
  container.add(backdrop);

  // Local card group for interactive transformation
  const cardGroup = new Group();
  container.add(cardGroup);

  // Card Dimensions (512x320 ratio ~ 1.6)
  const width = 2.4;
  const height = 1.5;
  const borderThickness = 0.04;

  // Contact Shadow Plane
  const shadowGeo = new PlaneGeometry(width * 1.2, 0.2);
  const shadowMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    roughness: 1.0
  });
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2.5;
  contactShadow.position.set(0, -height / 2 - 0.1, -0.1);
  cardGroup.add(contactShadow);

  // 2. High-contrast Rim/Accent Plate (Border/Edge)
  const borderGeo = new PlaneGeometry(width + borderThickness, height + borderThickness);
  const borderMat = new MeshStandardNodeMaterial({
    color: palette.surface,
    roughness: 0.2,
    metalness: 0.8,
    clearcoat: 0.2
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  cardGroup.add(borderMesh);

  // Accent highlight edge (revealed dynamically or styled statically)
  const accentEdgeGeo = new PlaneGeometry(width + borderThickness * 1.5, height + borderThickness * 1.5);
  const accentEdgeMat = new MeshStandardNodeMaterial({
    color: palette.accent,
    emissive: palette.accent,
    emissiveIntensity: 0.0 // starts dim, lights up on focus/hover
  });
  const accentEdgeMesh = new Mesh(accentEdgeGeo, accentEdgeMat);
  accentEdgeMesh.position.z = -0.02;
  cardGroup.add(accentEdgeMesh);

  // 3. Main Image & Card Surface
  const cardGeo = new PlaneGeometry(width, height);
  const cardMat = new MeshStandardNodeMaterial({
    color: palette.surface,
    roughness: 0.5,
    metalness: 0.3
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardGroup.add(cardMesh);

  // Load Image Asset safely
  const imageAssetUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  ctx.textureLoader.loadTexture(imageAssetUrl).then((tex) => {
    cardMat.map = tex;
    cardMat.needsUpdate = true;
  }).catch((err) => {
    console.warn('Failed to load image texture, using surface fallback', err);
  });

  // 4. Bottom Caption Strip
  const stripHeight = 0.3;
  const stripGeo = new PlaneGeometry(width, stripHeight);
  const stripMat = new MeshStandardNodeMaterial({
    color: palette.surface,
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
    opacity: 0.95
  });
  const stripMesh = new Mesh(stripGeo, stripMat);
  stripMesh.position.set(0, -height / 2 + stripHeight / 2, 0.01);
  cardGroup.add(stripMesh);

  // 5. Delicate local light to reveal machined-metal finishes
  const cardLight = new PointLight(palette.paper, 1.2, 5);
  cardLight.position.set(1.5, 1.0, 1.2);
  container.add(cardLight);

  const ambientFill = new PointLight(palette.accent, 0.4, 4);
  ambientFill.position.set(-1.5, -1.0, 0.5);
  container.add(ambientFill);

  // GSAP Animations and Handlers
  let hoverTimeline = null;

  const onPointerOver = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(cardGroup.position, {
      z: 0.15,
      y: 0.08,
      duration: 0.4,
      ease: 'power2.out'
    });
    hoverTimeline.to(cardGroup.rotation, {
      x: 0.04,
      y: -0.05,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
    hoverTimeline.to(accentEdgeMat, {
      emissiveIntensity: 1.5,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
  };

  const onPointerOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(cardGroup.position, {
      z: 0,
      y: 0,
      duration: 0.5,
      ease: 'power3.out'
    });
    hoverTimeline.to(cardGroup.rotation, {
      x: 0,
      y: 0,
      duration: 0.5,
      ease: 'power3.out'
    }, 0);
    hoverTimeline.to(accentEdgeMat, {
      emissiveIntensity: 0.0,
      duration: 0.4,
      ease: 'power3.out'
    }, 0);
  };

  const onClick = () => {
    ctx.emit('hub-journal.select', { id: config.id });

    // Press-down micro-interaction
    const clickTimeline = gsap.timeline();
    clickTimeline.to(cardGroup.scale, {
      x: 0.95,
      y: 0.95,
      z: 0.95,
      duration: 0.1,
      ease: 'power2.out'
    });
    clickTimeline.to(cardGroup.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.3,
      ease: 'back.out(1.7)'
    });
  };

  // Wire interactives inside userData handlers
  container.userData = {
    handlers: {
      pointerover: onPointerOver,
      pointerout: onPointerOut,
      click: onClick
    },
    cleanup: () => {
      if (hoverTimeline) hoverTimeline.kill();
      // Dispose Geometries
      backdropGeo.dispose();
      shadowGeo.dispose();
      borderGeo.dispose();
      accentEdgeGeo.dispose();
      cardGeo.dispose();
      stripGeo.dispose();
      // Dispose Materials
      backdropMat.dispose();
      shadowMat.dispose();
      borderMat.dispose();
      accentEdgeMat.dispose();
      cardMat.dispose();
      stripMat.dispose();
    }
  };

  return container;
}
